contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address spender, uint256 value) public {
        require(spender != address(0));

        uint256 beforeAllowance = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        bool success;
        bool ok = c.approve(spender, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = ok;
        }

        assert(
            success
                ? c.allowance(address(this), spender) == value
                : c.allowance(address(this), spender) == beforeAllowance
        );
    }

    receive() external payable {}
}

