contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(address spender, uint256 value) internal {
        vm.assume(spender != address(0));
        uint256 beforeAllowance;
        try c.allowance(address(this), spender) returns (uint256 __r) { beforeAllowance = __r; } catch { return; }
        bool success;
        try c.approve(spender, value) returns (bool ok) {
            success = ok;
        } catch {
            success = false;
        }
        assertTrue(success
                ? c.allowance(address(this), spender) == value
                : c.allowance(address(this), spender) == beforeAllowance);
    }

